#include <iostream>
#include <fstream>
using namespace std;

bool wszystkieParzyste(int n) {
    while (n > 0) {
        if ((n % 10) % 2 != 0) return false;
        n /= 10;
    }
    return true;
}

int main() {
    ifstream plik("liczby.txt");
    int n;
    int ile = 0, suma = 0;
    cout << "Liczby ze wszystkimi cyframi parzystymi:" << endl;
    while (plik >> n) {
        if (wszystkieParzyste(n)) {
            cout << "   " << n << endl;
            ile++;
            suma += n;
        }
    }
    cout << "Ilosc: " << ile << endl;
    cout << "Suma: " << suma << endl;
    return 0;
}
